  if line.startswith('|'):
   for d in ds: print(n,d,idx.count('"'`'"'+d+'"'`'"'))
print('COVERAGE IDS')
y=pathlib.Path('lean/coverage.yaml').read_text().splitlines(); ids=set(re.findall(r'"'^- id: (.+)$'"',pathlib.Path('lean/claims.yaml').read_text(),re.M))
for a,b in [(27,58),(629,646),(1402,1439),(1706,1742)]:
 found=re.findall(r'"'^  - (stratonovich-'"\\S+)"'$'"','\\n'.join(y[a:b]),re.M)
 print(a+1,b,len(found),'missing:',[v for v in found if v not in ids])
PY"

